const whatsappUrl = "https://wa.me/9779746955071"; const products = [ { name: "Classic T-Shirt", price: 999, category: "tshirts", image: "assets/img/classic-tshirt-225.jpg", tag: "Streetwear T-Shirts" }, { name: "Street Hoodie", price: 1999, category: "hoodies", image: "assets/img/anime-hoodie-naruto-480.jpg", srcset: "assets/img/anime-hoodie-naruto-480.jpg 480w, assets/img/anime-hoodie-naruto-768.jpg 768w", tag: "Anime Hoodies" }, { name: "Oversized Hoodie", price: 2199, category: "hoodies", image: "assets/img/oversized-anime-hoodie-480.jpg", srcset: "assets/img/oversized-anime-hoodie-480.jpg 480w, assets/img/oversized-anime-hoodie-768.jpg 768w", tag: "Oversized Hoodies" }, { name: "Casual Shirt", price: 1499, category: "tshirts", image: "assets/img/casual-shirt-225.jpg", tag: "Streetwear T-Shirts" }, { name: "Premium Streetwear Layer", price: 2499, category: "hoodies", image: "assets/img/premium-streetwear-layer-480.jpg", srcset: "assets/img/premium-streetwear-layer-480.jpg 480w, assets/img/premium-streetwear-layer-768.jpg 768w", tag: "Oversized Hoodies" }, { name: "Anime Graphic Fit", price: 2299, category: "hoodies", image: "assets/img/anime-graphic-fit-480.jpg", srcset: "assets/img/anime-graphic-fit-480.jpg 480w, assets/img/anime-graphic-fit-768.jpg 768w", tag: "Anime Hoodies" }, { name: "Street Design 1", price: 1799, category: "designs", image: "assets/img/street-design-1-480.jpg", srcset: "assets/img/street-design-1-480.jpg 480w, assets/img/street-design-1-768.jpg 768w", tag: "Streetwear Designs" }, { name: "Street Design 2", price: 1899, category: "designs", image: "assets/img/street-design-2-480.jpg", srcset: "assets/img/street-design-2-480.jpg 480w, assets/img/street-design-2-768.jpg 768w", tag: "Streetwear Designs" }, { name: "Street Design 3", price: 1799, category: "designs", image: "assets/img/street-design-3-480.jpg", srcset: "assets/img/street-design-3-480.jpg 480w, assets/img/street-design-3-768.jpg 768w", tag: "Streetwear Designs" }, { name: "Street Design 4", price: 1699, category: "designs", image: "assets/img/street-design-4-480.jpg", srcset: "assets/img/street-design-4-480.jpg 480w, assets/img/street-design-4-768.jpg 768w", tag: "Streetwear Designs" }, { name: "Street Design 5", price: 1999, category: "designs", image: "assets/img/street-design-5-480.jpg", srcset: "assets/img/street-design-5-480.jpg 480w, assets/img/street-design-5-768.jpg 768w", tag: "Streetwear Designs" } ]; const formatPrice = (price) => new Intl.NumberFormat("en-NP", { style: "currency", currency: "NPR", maximumFractionDigits: 0 }).format(price); const getAltText = (product) => { if (product.category === "hoodies") return `${product.name} anime hoodie Nepal oversized streetwear`; if (product.category === "tshirts") return `${product.name} streetwear t-shirt Kathmandu Nepal`; return `${product.name} streetwear design Nepal AR Clothing Zone`; }; function getVisibleProducts(category = "all") { const searchInput = document.getElementById("shop-search"); const sortSelect = document.getElementById("shop-sort"); const query = searchInput?.value.trim().toLowerCase() || ""; let visibleProducts = category === "all" ? [...products] : products.filter((product) => product.category === category); if (query) { visibleProducts = visibleProducts.filter((product) => `${product.name} ${product.tag} ${product.category}`.toLowerCase().includes(query)); } if (sortSelect?.value === "price-low") { visibleProducts.sort((a, b) => a.price - b.price); } else if (sortSelect?.value === "price-high") { visibleProducts.sort((a, b) => b.price - a.price); } else if (sortSelect?.value === "name") { visibleProducts.sort((a, b) => a.name.localeCompare(b.name)); } return visibleProducts; } function renderProducts(category = "all") { const container = document.getElementById("product-container"); if (!container) return; const visibleProducts = getVisibleProducts(category); if (!visibleProducts.length) { container.innerHTML = '<p class="empty-state">No products found in this category.</p>'; return; } container.innerHTML = visibleProducts.map((product) => ` <div class="col-md-4 col-lg-3"> <article class="product card h-100"> <div class="product-image"> <img src="${product.image}" ${product.srcset ? `srcset="${product.srcset}" sizes="(min-width: 992px) 25vw, (min-width: 768px) 33vw, 92vw"` : ""} alt="${getAltText(product)}" loading="lazy" decoding="async" width="480" height="720"> </div> <div class="product-details"> <span class="product-badge">${product.category === "hoodies" ? "Trending" : product.category === "designs" ? "Custom" : "Essential"}</span> <span>${product.tag}</span> <h3 class="h5">${product.name}</h3> <p>${formatPrice(product.price)}</p> <button type="button" class="btn btn-outline-dark w-100" data-add-cart="${product.name}">Quick add</button> <a href="${whatsappUrl}" target="_blank" rel="noopener noreferrer" class="btn btn-dark w-100 mt-auto" aria-label="Order ${product.name} on WhatsApp">Order via WhatsApp</a> </div> </article> </div> `).join(""); } function setupProductFilters() { const buttons = document.querySelectorAll(".filter-btn"); const params = new URLSearchParams(window.location.search); const validCategories = ["all", "hoodies", "tshirts", "designs"]; const activeCategory = validCategories.includes(params.get("category")) ? params.get("category") : "all"; buttons.forEach((button) => { button.classList.toggle("active", button.dataset.filter === activeCategory); button.addEventListener("click", () => { buttons.forEach((item) => item.classList.remove("active")); button.classList.add("active"); renderProducts(button.dataset.filter); }); }); document.getElementById("shop-search")?.addEventListener("input", () => renderProducts(document.querySelector(".filter-btn.active")?.dataset.filter || "all")); document.getElementById("shop-sort")?.addEventListener("change", () => renderProducts(document.querySelector(".filter-btn.active")?.dataset.filter || "all")); renderProducts(activeCategory); } document.addEventListener("click", (event) => { const button = event.target.closest("[data-add-cart]"); const toast = document.querySelector("[data-cart-toast]"); if (!button || !toast) return; toast.textContent = `${button.dataset.addCart} added to your style shortlist.`; toast.classList.remove("is-visible"); requestAnimationFrame(() => toast.classList.add("is-visible")); }); document.addEventListener("DOMContentLoaded", setupProductFilters, { once: true });